         );
CREATE TABLE session_inbox (
             id INTEGER PRIMARY KEY AUTOINCREMENT,
             session_id TEXT NOT NULL
                 REFERENCES sessions(session_id) ON DELETE CASCADE,
             delivery TEXT NOT NULL CHECK (delivery IN ('steer', 'queue')),
